        ).rstrip("\n")

        result = f"---\n{fm_yaml}\n---\n" + body
        result, links_resolved = self.resolve_links(result, source, target)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(result, encoding="utf-8")
        return links_resolved

